class Solution {
    public int minimumDifference(int[] nums){
        int n=nums.length/2;
        List<Long>[] left=new List[n+1],right=new List[n+1];
        for(int i=0;i<=n;i++){
            left[i]=new ArrayList<>();
            right[i]=new ArrayList<>();
        }
        long total=0;
        for(int value:nums)total+=value;
        for(int mask=0;mask<(1<<n);mask++){
            long a=0,b=0;
            int count=Integer.bitCount(mask);
            for(int bit=0;bit<n;bit++)if((mask&(1<<bit))!=0){
                a+=nums[bit];
                b+=nums[n+bit];
            }
            left[count].add(a);
            right[count].add(b);
        }
        for(List<Long> values:right)Collections.sort(values);
        long answer=Long.MAX_VALUE;
        for(int count=0;count<=n;count++)for(long a:left[count]){
            List<Long> values=right[n-count];
            long target=total/2-a;
            int index=Collections.binarySearch(values,target);
            if(index<0)index=-index-1;
            for(int position=Math.max(0,index-1);position<Math.min(values.size(),index+2);position++)answer=Math.min(answer,Math.abs(total-2*(a+values.get(position))));
        }
        return (int)answer;
    }
}

